	runCmd.Flags().String("devtools-server-address", "", "When this value is provided, the Flutter tool will not spin up a new DevTools server instance, and will instead use the one provided at the given address. Ignored if \"--no-devtools\" is specified.")
	runCmd.Flags().Bool("disable-dds", false, "(deprecated; use \"--no-dds\" instead) Disable the Dart Developer Service (DDS).")
	runCmd.Flags().Bool("disable-service-auth-codes", false, "(deprecated) Allow connections to the VM service without using authentication codes. (Not recommended! This can open your device to remote code execution attacks!)")
