	runCmd.Flags().Bool("enable-dart-profiling", false, "Whether the Dart VM sampling CPU profiler is enabled. This flag is only meaningful in debug and profile builds.")
	runCmd.Flags().Bool("enable-embedder-api", false, "Whether to enable the experimental embedder API on iOS.")
	runCmd.Flags().StringSlice("enable-experiment", nil, "The name of an experimental Dart feature to enable. Multiple experiments can be enabled by repeating \"--enable-experiment\".")
	runCmd.Flags().Bool("enable-flutter-gpu", false, "Whether to enable the Flutter GPU API (https://api.flutter.dev/flutter/flutter_gpu/). This feature is only supported with the Impeller rendering engine, which can be enabled via the \"--enable-impeller\" option.")
	runCmd.Flags().Bool("enable-hcpp", false, "Enable the use of the HCPP platform view rendering mode on the Impeller rendering backend. An explicit value takes priority over the EnableHcpp metadata in AndroidManifest.xml: build commands write it into the manifest of the artifact they produce, and \"run\", \"test\", and \"drive\" additionally apply it at launch. Without the flag, the manifest decides, and if the manifest does not set it either, the enable-hcpp feature flag does.")
	runCmd.Flags().Bool("enable-impeller", false, "Whether to enable the Impeller rendering engine. Impeller is the default renderer on iOS. On Android, Impeller is available but not the default. This flag will cause Impeller to be used on Android. On other platforms, this flag will be ignored.")
