	runCmd.Flags().String("frontend-server-starter-path", "", "When this value is provided, the frontend server will be started in JIT mode from the specified file, instead of from the AOT snapshot shipped with the Dart SDK. The specified file can either be a dart source file or a kernel file. This flag is not used by most normal users and is for backend testing only.")
	runCmd.Flags().BoolP("help", "h", false, "Print this usage information.")
	runCmd.Flags().String("host-vmservice-port", "", "When a device-side vmservice port is forwarded to a host-side port, use this value as the host port. Specifying port 0 (the default) will find a random free host port.")
	runCmd.Flags().Bool("hot", false, "Run with support for hot reloading. Only available for debug mode. Not available with \"--trace-startup\".")
	runCmd.Flags().Bool("ignore-deprecation", false, "Indicates that the app should ignore deprecation warnings and continue to build using deprecated APIs. Use of this flag may cause your app to fail to build when deprecated APIs are removed.")
	runCmd.Flags().String("initialize-from-dill", "", "Initializes the resident compiler with a specific kernel file instead of the default cached location.")
	runCmd.Flags().Bool("ios-profile-debugger", false, "Whether to attach the LLDB debugger when running in profile mode on a physical iOS device. Only available with Xcode 26.")
