	runCmd.Flags().Bool("no-android-skip-build-dependency-validation", false, "Skips Android Gradle project dependency verification.")
	runCmd.Flags().Bool("no-assume-initialize-from-dill-up-to-date", false, "If set, assumes that the file passed in initialize-from-dill is up to date and skip the check and potential invalidation of files.")
