	runCmd.Flags().Bool("no-deprecated-js-interop", false, "Whether to allow the deprecated JS interop libraries (such as \"dart:html\", \"dart:js\", and \"dart:js_util\") when compiling to JavaScript. With \"--no-deprecated-js-interop\", importing these libraries is a compile-time error and conditional imports on them resolve to false. Use this to find code that still needs to migrate to \"package:web\" and \"dart:js_interop\". If not specified, the Dart compiler default is used. Has no effect when compiling to WebAssembly.")
